STEP_ALLOWED = {
    "0": {"1"},
    "1": {"2"},
    "2": set(),
}


def step_allowed(current, nxt):
    """判断当前步骤能否进入下一步。"""
    if not current:
        return False
    return current in STEP_ALLOWED.get(nxt, set())

